INSERT INTO `testimoni` (`id`, `nama`, `jabatan`, `isi_testimoni`, `foto_profil`, `created_at`) VALUES
(1, 'Elis Masitoh, S.SiT, MM.', 'Direktur ITKAK Kementerian Perindustrian RI', 'DQ adalah lembaga resmi dari pemerintah, serta Zakat Infaq dan Sedekah  yang diberikan oleh saudara muslimin-muslimat sekalian insya Allah akan disalurkan dengan amanah dan tepat sasaran.', 'testimoni/6a56f591c8d14_1784083857.png', '2026-07-14 04:43:55'),
(2, 'Dr. dr. Kurnia Penta Seputra, Sp. U(k)', 'Ahli Urologi di RSUD Saiful Anwar Malang', 'DQ adalah lembaga yang bisa dipegang amanahnya, memegang amanah dari kita semua, dan disalurkan kepada masyarakat yang membutuhkan dan untuk pengembangan Islam di Indonesia.', 'testimoni/6a56f68e73648_1784084110.png', '2026-07-15 02:55:10'),
(3, 'dr. Orizanov Mahisa', 'Spesialis Anestesiologi dan Terapi Intensif', 'Amanah, profesional, dan insya Allah akan disalurkan sesuai dengan apa yang akan diprogramkan, dan saya rasa bisa memberikan manfaat untuk seluruh umat.', 'testimoni/6a56f6cfde55b_1784084175.png', '2026-07-15 02:56:15'),
(4, 'Dr. Tri Arief Sardjono, S.T., M.T.', 'Rektor Institut Teknologi Telkom Surabaya', 'Insya Allah terpercaya dan amanah karena di bawah arahan Kementerian Agama, dan berkenan berkontribusi untuk pendidikan mahasiswa yang kurang mampu, monggo manfaatkan sebagian hartanya dengan berzakat, insya Allah DQ akan menyalurkan ke yang benar-benar membutuhkan.', 'testimoni/6a56f72804562_1784084264.png', '2026-07-15 02:57:44'),
(5, 'Kelompok Penerima Manfaat Rombong Berkah', 'Penerima Bantuan Rombong Berkah', 'Saya mengucapkan terima kasih kepada DQ yang telah memberikan bantuan usaha berupa Rombong Berkah, semoga dapat memberikan barokah dan membantu perekonomian kami sebagai pedagang.', 'testimoni/6a56f76828144_1784084328.png', '2026-07-15 02:58:48');

